SELECT group_name AS groupName, MAX(campus) AS campus, MAX(member_count) AS memberCount, SUM(total_entries) AS totalEntries, COUNT(DISTINCT snapshot_date) AS activeDays FROM student_activity_snapshot WHERE snapshot_date BETWEEN #{startDate} AND #{endDate}
AND group_name LIKE CONCAT('%', #{keyword}, '%')
AND campus = #{campus}
GROUP BY group_name

SELECT DISTINCT group_name
FROM student_activity_snapshot
WHERE snapshot_date BETWEEN #{startDate} AND #{endDate}
